// tag-error.json

/** Where in the tag it failed: its boot, its config fetch, a command the site called, a pageview, a route change, the transport that posts batches to POST /v1/e (a batch the collector refused, or a failure in a flush), or a consent source the tag follows (an update read from Google Consent Mode's dataLayer). */
export type TagErrorStage = "boot" | "config" | "command" | "pageview" | "route" | "transport" | "consent";

/** The error's name, such as TypeError or ConfigError. */
export type TagErrorName = string;

/** A failure inside the tag, which its error boundary caught instead of throwing into the host page: the request body of POST /v1/t. It is sent in every consent state, so it carries nothing about the visitor or the page: no visitor or session id, no URL, no referrer, no client_ts. It is sent from a sample of page loads, without cookies, at most a few per page. */
export interface WireTagError {
  /** The wire schema's major version: this file's. */
  schema_version: 1;
  /** Random per report, for idempotent storage only. Its embedded time is the start of the client's hour, as a ping's is, never the millisecond. */
  event_id: Uuidv7;
  tag_version: TagVersion;
  /** The site the tag was installed for; absent when the failure is that the snippet names no valid site. */
  site_id?: SiteId;
  stage: TagErrorStage;
  name: TagErrorName;
  /** The error's message, scrubbed by the tag: each URL in it cut to its scheme and host, and each email address replaced. */
  message?: string;
}

export const WIRE_TAG_ERROR_FIELDS = ["schema_version", "event_id", "tag_version", "site_id", "stage", "name", "message"] as const;

export const WIRE_TAG_ERROR_REQUIRED = ["schema_version", "event_id", "tag_version", "stage", "name"] as const;

export const WIRE_TAG_ERROR_TYPES = { schema_version: "integer", event_id: "string", tag_version: "string", site_id: "string", stage: "string", name: "string", message: "string" } as const;

export const WIRE_TAG_ERROR_VALUES = { schema_version: [1], stage: ["boot", "config", "command", "pageview", "route", "transport", "consent"] } as const;

export const WIRE_TAG_ERROR_PATTERN = { event_id: "^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$", tag_version: "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\\+[0-9A-Za-z.-]+)?$", site_id: "^[A-Za-z0-9_-]+$" } as const;

export const WIRE_TAG_ERROR_MAX_LENGTH = { tag_version: 64, site_id: 64, name: 64, message: 256 } as const;

// withdrawal.json

/** The withdrawal signal, the request body of POST /v1/w (AAI-785): a visitor who had granted analytics consent withdrew it, on a site whose config turns purge on withdrawal on (consent.purge_on_withdrawal, AAI-226). The tag sends it once, with the visitor id of its _amnda_id cookie, just before it deletes the visitor's cookies; the processor then erases that visitor's stored data through the DSAR cascade delete and writes an audit row. It carries nothing about the page (no URL, referrer, session or consent snapshot): only what the erasure needs. It is sent without cookies, so that no collector behind a first-party proxy can re-issue the cookies being deleted. A site with the option off never sends it. */
export interface WireWithdrawal {
  /** The wire schema's major version: this file's. */
  schema_version: 1;
  /** Minted by the tag for each signal; with site_id, the key that makes redelivery idempotent. */
  event_id: Uuidv7;
  tag_version: TagVersion;
  site_id: SiteId;
  /** The visitor whose stored data the site's option erases: the id of the _amnda_id cookie the tag is about to delete. */
  visitor_id: Uuidv7;
  /** When the visitor withdrew, by the browser's clock: Unix epoch milliseconds. */
  client_ts: ClientTs;
  type?: never;
  url?: never;
  referrer?: never;
  page_title?: never;
  language?: never;
  session_id?: never;
  consent?: never;
  attribution?: never;
  props?: never;
  user_ref?: never;
  link_host?: never;
  purchase?: never;
  engagement_ms?: never;
  link_scheme?: never;
  path?: never;
  referrer_host?: never;
  utm?: never;
  click_ids?: never;
  stage?: never;
  name?: never;
}

export const WIRE_WITHDRAWAL_FIELDS = ["schema_version", "event_id", "tag_version", "site_id", "visitor_id", "client_ts"] as const;

export const WIRE_WITHDRAWAL_REQUIRED = ["schema_version", "event_id", "tag_version", "site_id", "visitor_id", "client_ts"] as const;

export const WIRE_WITHDRAWAL_TYPES = { schema_version: "integer", event_id: "string", tag_version: "string", site_id: "string", visitor_id: "string", client_ts: "integer" } as const;

export const WIRE_WITHDRAWAL_VALUES = { schema_version: [1] } as const;

export const WIRE_WITHDRAWAL_MINIMUM = { client_ts: 0 } as const;

export const WIRE_WITHDRAWAL_PATTERN = { event_id: "^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$", tag_version: "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\\+[0-9A-Za-z.-]+)?$", site_id: "^[A-Za-z0-9_-]+$", visitor_id: "^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$" } as const;

export const WIRE_WITHDRAWAL_MAX_LENGTH = { tag_version: 64, site_id: 64 } as const;

